import { Component, OnInit } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';

interface LicnaKarta {
  id: number;
  ime: string;
  prezime: string;
  jmbg: string;
  datumIzdavanja: string;
  datumVazenja: string;
  grad: string;
  drzava: string;
  status: string;
}

@Component({
  selector: 'app-licna',
  templateUrl: './licna.component.html',
  styleUrls: ['./licna.component.css']
})
export class LicnaComponent implements OnInit {

  zahtevi: LicnaKarta[] = [];
  token: string = ''; // ovde stavi JWT token koji čuvaš pri login-u

  constructor(private http: HttpClient) { }

  ngOnInit(): void {
    this.ucitajZahteve();
  }

  ucitajZahteve() {
    const headers = new HttpHeaders().set('Authorization', `Bearer ${this.token}`);
    this.http.get<LicnaKarta[]>('http://localhost:8080/licna-karta/svi-zahtevi', { headers })
      .subscribe({
        next: (data) => this.zahtevi = data,
        error: (err) => console.error(err)
      });
  }

  podnesiZahtev() {
    // ovde možeš otvoriti modal ili redirect ka formi za podnošenje zahteva
  }

  produziLicnu() {
    // ovde možeš otvoriti modal ili redirect ka produžavanju lične
  }

}
